import numpy as np
import os

try:
    from scipy.optimize import linprog
except Exception:
    linprog = None

try:
    from scipy.linalg import null_space as scipy_null_space
except Exception:
    scipy_null_space = None

N = 32
R_MIN = 1e-8
TOL_CONTACT = 1e-12
TOL_BOUND = 1e-12

# Tiny float-safe margins
PAIR_EPS = 5e-16     # extra reduction beyond exact excess for pair overlaps
GLOBAL_NUDGE = 2e-16 # final uniform shrink to guarantee strict ≤

def _pair_indices(n=N):
    return [(i, j) for i in range(n) for j in range(i + 1, n)]
PAIRS = _pair_indices(N)

# ---------- Exact zero-slack radii LP ----------
def _solve_radii_zero_slack(centers):
    n = centers.shape[0]
    x = centers[:, 0]; y = centers[:, 1]
    rows = []; rhs = []

    # boundary constraints r_i <= x_i, 1-x_i, y_i, 1-y_i
    for i in range(n):
        a = np.zeros(n); a[i] = 1.0; rows.append(a); rhs.append(max(0.0, float(x[i])))
    for i in range(n):
        a = np.zeros(n); a[i] = 1.0; rows.append(a); rhs.append(max(0.0, float(1.0 - x[i])))
    for i in range(n):
        a = np.zeros(n); a[i] = 1.0; rows.append(a); rhs.append(max(0.0, float(y[i])))
    for i in range(n):
        a = np.zeros(n); a[i] = 1.0; rows.append(a); rhs.append(max(0.0, float(1.0 - y[i])))

    # pairwise r_i + r_j <= d_ij
    for (i, j) in PAIRS:
        a = np.zeros(n); a[i] = 1.0; a[j] = 1.0
        dij = float(np.linalg.norm(centers[i] - centers[j]))
        rows.append(a); rhs.append(max(0.0, dij))

    A_ub = np.vstack(rows); b_ub = np.array(rhs)
    c = -np.ones(n)
    bounds = [(R_MIN, None) for _ in range(n)]

    if linprog is None:
        r = np.minimum.reduce([x, 1.0 - x, y, 1.0 - y])
        r = np.maximum(R_MIN, r)
        for (i, j) in PAIRS:
            dij = float(np.linalg.norm(centers[i] - centers[j]))
            s = r[i] + r[j]
            if s > dij:
                need = s - dij + PAIR_EPS
                di = min(0.5 * need, max(0.0, r[i] - R_MIN))
                dj = min(0.5 * need, max(0.0, r[j] - R_MIN))
                r[i] = max(R_MIN, r[i] - di); r[j] = max(R_MIN, r[j] - dj)
        return r, False

    res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method="highs")
    if not res.success:
        r = np.minimum.reduce([x, 1.0 - x, y, 1.0 - y])
        r = np.maximum(R_MIN, 0.99 * r)
        for (i, j) in PAIRS:
            dij = float(np.linalg.norm(centers[i] - centers[j]))
            s = r[i] + r[j]
            if s > dij:
                need = s - dij + PAIR_EPS
                di = min(0.5 * need, max(0.0, r[i] - R_MIN))
                dj = min(0.5 * need, max(0.0, r[j] - R_MIN))
                r[i] = max(R_MIN, r[i] - di); r[j] = max(R_MIN, r[j] - dj)
        return r, False
    return np.maximum(R_MIN, np.array(res.x, dtype=float)), True

# ---------- Robust zero-tolerance finalize (iterative, float-safe) ----------
def _finalize_zero_tol(C, r, max_iter=12):
    r = np.array(r, dtype=float).copy()
    n = C.shape[0]
    x, y = C[:, 0], C[:, 1]

    def clamp_bounds(rr):
        changed = False
        for i in range(n):
            bmax = min(x[i], 1.0 - x[i], y[i], 1.0 - y[i])
            if rr[i] > bmax:
                rr[i] = max(R_MIN, bmax)
                changed = True
            elif rr[i] < R_MIN:
                rr[i] = R_MIN
                changed = True
        return changed

    for _ in range(max_iter):
        changed = False
        # Enforce boundaries
        if clamp_bounds(r):
            changed = True
        # Enforce pairwise non-overlap with tiny extra reduction
        for (i, j) in PAIRS:
            dij = float(np.linalg.norm(C[i] - C[j]))
            s = r[i] + r[j]
            if s > dij:
                need = (s - dij) + PAIR_EPS
                # symmetric reduction with capacity checks
                di_cap = max(0.0, r[i] - R_MIN)
                dj_cap = max(0.0, r[j] - R_MIN)
                if di_cap + dj_cap <= 0.0:
                    continue
                di = min(0.5 * need, di_cap)
                dj = min(need - di, dj_cap)
                # If still leftover due to caps, try flipping distribution
                rem = need - (di + dj)
                if rem > 0 and di < di_cap:
                    take = min(rem, di_cap - di); di += take; rem -= take
                if rem > 0 and dj < dj_cap:
                    take = min(rem, dj_cap - dj); dj += take; rem -= take
                r[i] = max(R_MIN, r[i] - di)
                r[j] = max(R_MIN, r[j] - dj)
                changed = True
        if not changed:
            break

    # Final global nudge to guarantee strict ≤ under rounding
    r = np.maximum(R_MIN, r - GLOBAL_NUDGE)

    return r

# ---------- Active set detection ----------
def _active_sets(C, r, tol_pair=TOL_CONTACT, tol_bound=TOL_BOUND):
    n = C.shape[0]
    pairs_active = []
    for (i, j) in PAIRS:
        dij = float(np.linalg.norm(C[i] - C[j]))
        if abs(dij - (r[i] + r[j])) <= tol_pair:
            pairs_active.append((i, j))
    boundary = {i: [] for i in range(n)}
    x, y = C[:, 0], C[:, 1]
    for i in range(n):
        if abs(r[i] - x[i]) <= tol_bound: boundary[i].append(("x_left",))
        if abs(r[i] - (1.0 - x[i])) <= tol_bound: boundary[i].append(("x_right",))
        if abs(r[i] - y[i]) <= tol_bound: boundary[i].append(("y_bottom",))
        if abs(r[i] - (1.0 - y[i])) <= tol_bound: boundary[i].append(("y_top",))
    return pairs_active, boundary

# ---------- Free-set selection (deterministic) ----------
def _select_free_sets(C, r, pairs_active, boundary, sizes=(3, 4, 5)):
    n = C.shape[0]
    deg = np.zeros(n, dtype=int)
    for (i, j) in pairs_active:
        deg[i] += 1; deg[j] += 1
    for i in range(n):
        deg[i] += len(boundary.get(i, []))
    order = np.argsort(deg)  # low-degree first
    sets = []
    for s in sizes:
        F = tuple(order[:s].tolist()); sets.append(F)
    for s in sizes:
        start = min(3, N - s)
        F = tuple(order[start:start + s].tolist()); sets.append(F)
    uniq, seen = [], set()
    for F in sets:
        if F not in seen:
            uniq.append(list(F)); seen.add(F)
    return uniq

# ---------- Build equality matrix E δ = 0 for a given free set F ----------
def _build_equalities(C, pairs_active, boundary, F):
    idx = {i: k for k, i in enumerate(F)}
    m = len(F)
    rows = []

    for (i, j) in pairs_active:
        ci, cj = C[i], C[j]
        d = ci - cj
        norm = float(np.linalg.norm(d))
        if norm < 1e-15:
            continue
        u = d / norm
        if (i in idx) and (j in idx):
            row = np.zeros(2 * m); ii = idx[i]; jj = idx[j]
            row[2 * ii + 0] = u[0]; row[2 * ii + 1] = u[1]
            row[2 * jj + 0] -= u[0]; row[2 * jj + 1] -= u[1]
            rows.append(row)
        elif (i in idx) and (j not in idx):
            row = np.zeros(2 * m); ii = idx[i]
            row[2 * ii + 0] = u[0]; row[2 * ii + 1] = u[1]
            rows.append(row)
        elif (j in idx) and (i not in idx):
            row = np.zeros(2 * m); jj = idx[j]
            row[2 * jj + 0] = -u[0]; row[2 * jj + 1] = -u[1]
            rows.append(row)

    for i in F:
        bs = boundary.get(i, [])
        for tag in bs:
            t = tag[0]
            row = np.zeros(2 * m)
            if t in ("x_left", "x_right"):
                row[2 * idx[i] + 0] = 1.0; rows.append(row)
            elif t in ("y_bottom", "y_top"):
                row[2 * idx[i] + 1] = 1.0; rows.append(row)

    E = np.vstack(rows) if len(rows) > 0 else np.zeros((0, 2 * m))
    return E

def _nullspace(E, rtol=1e-12):
    if scipy_null_space is not None:
        try:
            NS = scipy_null_space(E, rcond=rtol)
            return NS
        except Exception:
            pass
    if E.size == 0:
        return np.eye(E.shape[1])
    U, S, Vh = np.linalg.svd(E, full_matrices=True)
    tol = rtol * (S[0] if S.size > 0 else 1.0)
    r = int(np.sum(S > tol))
    NS = Vh[r:, :].T
    return NS

def _direction_vector(C, F):
    m = len(F)
    dvec = np.zeros(2 * m)
    for k, i in enumerate(F):
        acc = np.zeros(2)
        ci = C[i]
        for j in range(C.shape[0]):
            if j == i: continue
            cj = C[j]
            v = ci - cj
            dist = float(np.linalg.norm(v))
            if dist < 1e-12: continue
            acc += v / (dist * max(dist, 1e-6))
        dvec[2 * k + 0] = acc[0]; dvec[2 * k + 1] = acc[1]
    nrm = float(np.linalg.norm(dvec))
    return dvec / nrm if nrm > 1e-15 else dvec

def _asn_try_step(C, r, F, tau_list=(0.015, 0.01, 0.006, 0.004, 0.002), alphas=(1.0, 0.7, 0.5, 0.35, 0.2)):
    m = len(F)
    pairs_active, boundary = _active_sets(C, r)
    E = _build_equalities(C, pairs_active, boundary, F)
    NS = _nullspace(E, rtol=1e-12)
    if NS.shape[1] == 0:
        return None

    dvec = _direction_vector(C, F)
    g = NS.T @ dvec
    if float(np.linalg.norm(g)) < 1e-15:
        return None
    base = NS @ g

    for tau in tau_list:
        max_abs = float(np.max(np.abs(base))) if base.size > 0 else 0.0
        if max_abs < 1e-18:
            continue
        scale = min(1.0, tau / max_abs)
        step0 = base * scale
        for a in alphas:
            step = a * step0
            C_try = C.copy()
            for k, i in enumerate(F):
                C_try[i, 0] = np.clip(C_try[i, 0] + step[2 * k + 0], 0.0, 1.0)
                C_try[i, 1] = np.clip(C_try[i, 1] + step[2 * k + 1], 0.0, 1.0)
            r_try, _ = _solve_radii_zero_slack(C_try)
            r_try = _finalize_zero_tol(C_try, r_try, max_iter=12)
            gain = float(np.sum(r_try) - np.sum(r))
            print(f"[asn] F={F} tau={tau:.3f} alpha={a:.2f} gain={gain:.12f}")
            if gain > 1e-9:
                return (C_try, r_try, gain, tau, a)
    return None

def _load_storage_seed():
    try:
        C = np.load("storage/verity/best_centers.npy")
        if isinstance(C, np.ndarray) and C.shape == (N, 2):
            return np.clip(C.astype(float), 0.0, 1.0)
    except Exception:
        pass
    xs = np.linspace(0.1, 0.9, 6)
    ys = np.linspace(0.1, 0.9, 6)
    centers = []
    for ix, x in enumerate(xs):
        for iy, y in enumerate(ys):
            if (ix in (0, 5)) and (iy in (0, 5)):
                continue
            centers.append([x, y])
    return np.array(centers, dtype=float)

def construct_packing() -> tuple:
    C = _load_storage_seed()
    r, _ = _solve_radii_zero_slack(C)
    r = _finalize_zero_tol(C, r, max_iter=12)
    best_C = C.copy(); best_r = r.copy(); best_s = float(np.sum(r))

    pairs_active, boundary = _active_sets(C, r)
    free_sets = _select_free_sets(C, r, pairs_active, boundary, sizes=(3, 4, 5))

    accepted = 0
    for F in free_sets:
        res = _asn_try_step(best_C, best_r, F)
        if res is None:
            continue
        C_new, r_new, gain, tau, a = res
        s_new = float(np.sum(r_new))
        if s_new > best_s + 1e-9:
            best_C, best_r, best_s = C_new, r_new, s_new
            accepted += 1
            print(f"[asn] ACCEPT F={F} tau={tau:.3f} alpha={a:.2f} new_sum={best_s:.15f}")
            # Optional second step on same F
            res2 = _asn_try_step(best_C, best_r, F)
            if res2 is not None:
                C2, R2, gain2, tau2, a2 = res2
                s2 = float(np.sum(R2))
                if s2 > best_s + 1e-9:
                    best_C, best_r, best_s = C2, R2, s2
                    accepted += 1
                    print(f"[asn] ACCEPT2 F={F} tau={tau2:.3f} alpha={a2:.2f} new_sum={best_s:.15f}")
        if accepted >= 3:
            break

    try:
        os.makedirs("storage/verity", exist_ok=True)
        np.save("storage/verity/best_centers.npy", best_C)
        np.save("storage/verity/best_radii.npy", best_r)
        with open("storage/verity/evals_asn.tsv", "a") as f:
            f.write(f"best_sum\t{best_s:.15f}\n")
    except Exception:
        pass

    return np.array(best_C, dtype=float), np.array(best_r, dtype=float)
